<?php
namespace Delnavazan\Platform\Core\Infrastructure\Repository;

/** Persistence boundary for one confirmed introductory booking cancellation and its retraction outbox. */
final class ConfirmedIntroBookingCancellationRepository {
    private string $p;
    public function __construct(){global $wpdb;$this->p=$wpdb->prefix.'dzn_';}
    public function begin():void{global $wpdb;if($wpdb->query('SET TRANSACTION ISOLATION LEVEL READ COMMITTED')===false||$wpdb->query('START TRANSACTION')===false)throw new \RuntimeException('Transaction start failed');}
    public function commit():void{global $wpdb;if($wpdb->query('COMMIT')===false)throw new \RuntimeException('Transaction commit failed');}
    public function rollback():void{global $wpdb;$wpdb->query('ROLLBACK');}

    public function command(string $digest):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_cancellation_commands WHERE command_key_digest=%s",$digest))?:null;}
    public function confirmationByUid(string $uid,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT c.*,r.lifecycle_status,r.resolution_state,r.student_id,r.privacy_erased_at,d.state delivery_state,rt.starts_at_utc,rt.instructional_ends_at_utc ends_at_utc,rt.occupied_ends_at_utc,rt.timezone request_timezone FROM {$this->p}booking_request_confirmations c INNER JOIN {$this->p}booking_requests r ON r.id=c.booking_request_id INNER JOIN {$this->p}booking_request_teacher_deliveries d ON d.id=c.delivery_id INNER JOIN {$this->p}booking_request_requested_times rt ON rt.id=c.requested_time_id AND rt.booking_request_id=r.id WHERE c.uid=%s LIMIT 1{$suffix}",$uid))?:null;}
    public function cancellationForConfirmation(int $confirmationId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_cancellations WHERE confirmation_id=%d LIMIT 1{$suffix}",$confirmationId))?:null;}
    public function cancellation(int $id,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_cancellations WHERE id=%d LIMIT 1{$suffix}",$id))?:null;}
    public function retractionJobForCancellation(int $cancellationId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_provider_retraction_jobs WHERE cancellation_id=%d LIMIT 1{$suffix}",$cancellationId))?:null;}
    public function retractionJob(int $id,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_provider_retraction_jobs WHERE id=%d LIMIT 1{$suffix}",$id))?:null;}
    public function dueRetractionJobs(int $limit=10):array{global $wpdb;$limit=max(1,min(25,$limit));return(array)$wpdb->get_results("SELECT * FROM {$this->p}booking_request_provider_retraction_jobs WHERE (state IN ('queued','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (state='sending' AND lease_expires_at<=UTC_TIMESTAMP()) ORDER BY id LIMIT {$limit}");}
    public function projectionSecret(int $confirmationId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}provider_projection_secrets WHERE mapping_kind='booking_calendar' AND mapping_id=%d AND active_slot=1 LIMIT 1",$confirmationId))?:null;}
    public function credential(int $connectionId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}integration_credentials WHERE connection_id=%d AND state='active' ORDER BY id DESC LIMIT 1",$connectionId))?:null;}

    public function insertCancellation(array $data):int{return $this->insert('booking_request_cancellations',$data);}
    public function insertCommand(array $data):int{return $this->insert('booking_request_cancellation_commands',$data);}
    public function insertRetractionJob(array $data):int{return $this->insert('booking_request_provider_retraction_jobs',$data);}
    public function insertNotification(array $data):int{return $this->insert('booking_request_student_notifications',$data);}

    public function transitionConfirmation(int $id,int $expectedVersion,string $from,string $to,string $now,int $actor):void{global $wpdb;$changed=$wpdb->query($wpdb->prepare("UPDATE {$this->p}booking_request_confirmations SET state=%s,version=version+1,updated_at=%s,updated_by=%d WHERE id=%d AND version=%d AND state=%s",$to,$now,$actor,$id,$expectedVersion,$from));if($changed!==1)throw new \RuntimeException('Booking confirmation changed concurrently');}
    public function transitionDelivery(int $id,string $from,string $to,string $now):void{global $wpdb;$changed=$wpdb->update($this->p.'booking_request_teacher_deliveries',array('state'=>$to,'updated_at'=>$now),array('id'=>$id,'state'=>$from));if($changed!==1)throw new \RuntimeException('Booking delivery changed concurrently');}
    public function cancelRequest(int $id,string $fromResolution,string $toResolution,string $now,int $actor):void{global $wpdb;$changed=$wpdb->query($wpdb->prepare("UPDATE {$this->p}booking_requests SET resolution_state=%s,version=version+1,updated_at=%s,updated_by=%d WHERE id=%d AND lifecycle_status='closed' AND resolution_state=%s AND privacy_erased_at IS NULL",$toResolution,$now,$actor,$id,$fromResolution));if($changed!==1)throw new \RuntimeException('Booking request changed concurrently');}
    public function closeCoordinationCase(int $requestId,string $now,int $actor):void{global $wpdb;$wpdb->query($wpdb->prepare("UPDATE {$this->p}coordination_cases SET state='closed',state_reason_code='booking_cancelled',closed_at=%s,closed_by=%d,version=version+1,updated_at=%s WHERE booking_request_id=%d AND state<>'closed'",$now,$actor,$now,$requestId));}
    public function queueCancellationNotification(int $deliveryId,int $confirmationId,string $now):void{global $wpdb;$sql=$wpdb->prepare("INSERT INTO {$this->p}booking_request_student_notifications (uid,delivery_id,confirmation_id,notification_kind,state,attempt_count,next_attempt_at,lease_token_digest,lease_expires_at,last_error_code,handed_off_at,created_at,updated_at) VALUES (%s,%d,%d,'cancelled','queued',0,%s,NULL,NULL,NULL,NULL,%s,%s) ON DUPLICATE KEY UPDATE id=id",\Delnavazan\Platform\Core\Support\Identifier::uid(),$deliveryId,$confirmationId,$now,$now,$now);if($wpdb->query($sql)===false)throw new \RuntimeException('Booking cancellation notification persistence failed');}
    public function updateRetractionJob(int $id,array $where,array $data):void{global $wpdb;$changed=$wpdb->update($this->p.'booking_request_provider_retraction_jobs',$data,array_merge(array('id'=>$id),$where));if($changed!==1)throw new \RuntimeException('Booking retraction job changed concurrently');}
    public function retireSecret(int $id,int $actor,string $now):void{global $wpdb;$changed=$wpdb->update($this->p.'provider_projection_secrets',array('state'=>'retired','active_slot'=>null,'retired_at'=>$now,'retired_by'=>$actor),array('id'=>$id,'state'=>'active','active_slot'=>1));if($changed!==1)throw new \RuntimeException('Booking provider reference changed concurrently');}

    private function insert(string $table,array $data):int{global $wpdb;if($wpdb->insert($this->p.$table,$data)===false)throw new \RuntimeException('Booking cancellation persistence failed');return(int)$wpdb->insert_id;}
}
